BEGIN;
SELECT no_plan();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT set_config('test.content',api.save_library_content(NULL,'11111111-1111-4111-8111-111111111111','recipe','Receta prueba','Cenas','draft','{"minutes":20,"servings":2,"ingredients":"Arroz","steps":"Cocinar"}')::text,true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),1::bigint,'Author reads draft');
SELECT throws_ok($$SELECT api.save_library_content(NULL,'22222222-2222-4222-8222-222222222222','video','Ajeno','Guías','published','{"url":"https://example.com"}')$$,NULL,NULL,'Cannot write cross tenant');
SELECT throws_ok($$SELECT api.save_library_content(NULL,'11111111-1111-4111-8111-111111111111','video','Malo','Guías','published','{"url":"javascript:alert(1)"}')$$,NULL,NULL,'Reject unsafe links');
SELECT throws_ok($$SELECT api.save_library_content(NULL,'11111111-1111-4111-8111-111111111111','document','Ajeno','Guías','published','{"path":"other/file.pdf"}')$$,NULL,NULL,'Cannot attach another file');
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),0::bigint,'Patient cannot read draft');
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.save_library_content(id,organization_id,kind,title,category,'published',body,updated_at) FROM api.content_library WHERE id=current_setting('test.content')::uuid$$,'Publish');
SELECT throws_ok($$SELECT api.save_library_content(current_setting('test.content')::uuid,'11111111-1111-4111-8111-111111111111','recipe','Lost update','Cenas','draft','{"minutes":20,"servings":2,"ingredients":"Arroz","steps":"Cocinar"}',NULL)$$,NULL,NULL,'Reject stale edit');
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),1::bigint,'Assigned patient reads publication');
SELECT throws_ok($$SELECT api.save_library_content(NULL,'11111111-1111-4111-8111-111111111111','video','Hack','Guías','published','{"url":"https://example.com"}')$$,NULL,NULL,'Patient cannot write');
SELECT set_config('request.jwt.claims','{"sub":"b3333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),0::bigint,'Other professional denied');
SELECT set_config('request.jwt.claims','{"sub":"d3333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),0::bigint,'Other patient denied');
SELECT set_config('request.jwt.claims','{"sub":"b1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library),0::bigint,'Nonclinical owner denied');
SELECT set_config('request.jwt.claims','{"sub":"b4444444-4444-4444-8444-444444444444","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library),0::bigint,'Assistant denied');
SELECT set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000000","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library),0::bigint,'Platform admin denied');
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.save_library_content(id,organization_id,kind,title,category,'retired',body,updated_at) FROM api.content_library WHERE id=current_setting('test.content')::uuid$$,'Retire without deleting');
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.content_library WHERE id=current_setting('test.content')::uuid),0::bigint,'Retirement revokes patient read');
SELECT ok(NOT has_table_privilege('authenticated','app.content_library','INSERT'),'No direct write');
SELECT ok(NOT has_function_privilege('anon','api.save_library_content(uuid,uuid,text,text,text,text,jsonb,timestamptz)','EXECUTE'),'Anonymous RPC denied');
SELECT * FROM finish();
ROLLBACK;
